answer_code:
int can_finish(int num, const int *a, int n, int limit) {
    int used = 1, sum = 0;
    for (int i = 0; i < n; ++i) {
        if (a[i] > limit) return 0;
        if (sum + a[i] > limit) { ++used; sum = 0; }
        sum += a[i];
    }
    return used <= num;
}

