int push(Q *q, int x) {
    if (q->count == q->cap) return -1;
    q->data[q->tail] = x;
    q->tail = (q->tail + 1) % q->cap;
    q->count++;
    return 0;
}

int pop(Q *q, int *x) {
    if (q->count == 0) return -1;
    *x = q->data[q->head];
    q->head = (q->head + 1) % q->cap;
    q->count--;
    return 0;
}

