int min_len(int *a, int n, int target) {
    int sum = 0, left = 0, ans = n + 1;
    for (int right = 0; right < n; ++right) {
        sum += a[right];
        while (sum >= target) {
            int len = right - left + 1;
            if (len < ans) ans = len;
            sum -= a[left++];
        }
    }
    return ans == n + 1 ? 0 : ans;
}

