int merge_ranges(const int *a, int n, int out[][2]) {
    if (n <= 0) return 0;
    int k = 0;
    int l = a[0], r = a[0];
    for (int i = 1; i < n; ++i) {
        if (a[i] == r + 1) {
            r = a[i];
        } else {
            out[k][0] = l;
            out[k][1] = r;
            ++k;
            l = r = a[i];
        }
    }
    out[k][0] = l;
    out[k][1] = r;
    return k + 1;
}

