answer_code:
int min_len(int *a, int n, int target) {
    int l = 0, sum = 0, ans = n + 1;
    for (int r = 0; r < n; ++r) {
        sum += a[r];
        while (sum >= target) {
            int len = r - l + 1;
            if (len < ans) ans = len;
            sum -= a[l++];
        }
    }
    return ans == n + 1 ? 0 : ans;
}

