int drain_queue(VosPriQue *pq, int *out) {
    int n = 0;
    while (!VOS_PriQueEmpty(pq)) {
        int *top = (int *)VOS_PriQueTop(pq);
        out[n++] = *top;
        VOS_PriQuePop(pq);
    }
    return n;
}

